.cohortsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #20203a;
    background: linear-gradient(160deg, #f4f1ea 0%, #ece7f3 100%);
    border-radius: 18px;
}

.cohortsim-container * {
    box-sizing: border-box;
}

.cohortsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #221a4d 0%, #34276e 55%, #4a3a8c 100%);
    color: #f6f3ff;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(34, 26, 77, 0.32);
}

.cohortsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.cohortsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #e8c97a;
    background: rgba(255, 255, 255, 0.10);
    padding: 5px 14px;
    border-radius: 999px;
}

.cohortsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e6e0f5;
}

.cohortsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #3a2f6b;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.cohortsim-period-counter #currentDay,
.cohortsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #221a4d;
}

.cohortsim-round-name {
    background: #e0d8f2;
    color: #34276e;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.cohortsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a5b12;
    background: #faedd2;
    padding: 4px 12px;
    border-radius: 999px;
}

.cohortsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.cohortsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e1dbee;
    box-shadow: 0 4px 14px rgba(34, 26, 77, 0.06);
    border-top: 4px solid #4a3a8c;
}

.cohortsim-card-objfit { border-top-color: #34276e; }
.cohortsim-card-transfer { border-top-color: #1f7a6b; }
.cohortsim-card-sponsor { border-top-color: #2f6fb0; }
.cohortsim-card-margin { border-top-color: #b5891f; }

.cohortsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6a6388;
}

.cohortsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #221a4d;
}

.cohortsim-card-objfit .cohortsim-value { color: #34276e; }
.cohortsim-card-transfer .cohortsim-value { color: #1f7a6b; }
.cohortsim-card-sponsor .cohortsim-value { color: #2f6fb0; }
.cohortsim-card-margin .cohortsim-value { color: #b5891f; }

.cohortsim-sublabel {
    font-size: 0.76rem;
    color: #7d7699;
    line-height: 1.35;
}

.cohortsim-margin-fail .cohortsim-value { color: #c0392b; }
.cohortsim-margin-ok .cohortsim-value { color: #1f7a6b; }

.cohortsim-constraint-bar {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 12px;
    background: #221a4d;
    color: #efeaff;
    padding: 12px 16px;
    border-radius: 12px;
    margin-bottom: 18px;
}

.cohortsim-constraint {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.cohortsim-constraint-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    font-weight: 700;
    color: #b8acdf;
}

.cohortsim-constraint span:last-child {
    font-size: 1.08rem;
    font-weight: 800;
    letter-spacing: 0.3px;
}

.cohortsim-constraint.cohortsim-over span:last-child {
    color: #ff9d8a;
}

.cohortsim-constraint.cohortsim-under span:last-child {
    color: #ff9d8a;
}

.cohortsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #4a3a8c;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(34, 26, 77, 0.05);
}

.cohortsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.cohortsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #221a4d;
    margin-bottom: 6px;
}

.cohortsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3b3556;
}

.cohortsim-briefing-text strong { color: #1f7a6b; }
.cohortsim-briefing-text em { color: #9a5b12; font-style: italic; }

.cohortsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e1dbee;
    box-shadow: 0 4px 14px rgba(34, 26, 77, 0.06);
}

.cohortsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #221a4d;
    border-bottom: 2px solid #ece7f3;
    padding-bottom: 8px;
}

.cohortsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2c2552;
    margin: 14px 0 6px;
}

.cohortsim-container select,
.cohortsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cdc3e6;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #faf8ff;
    color: #20203a;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.cohortsim-container select:focus,
.cohortsim-container input[type="number"]:focus {
    outline: none;
    border-color: #4a3a8c;
    box-shadow: 0 0 0 3px rgba(74, 58, 140, 0.15);
}

.cohortsim-container select option {
    background-color: #ffffff;
    color: #20203a;
}

.cohortsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #4a3a8c;
}

.cohortsim-range-readout,
.cohortsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #34276e;
    margin-top: 4px;
}

.cohortsim-range-readout span:last-child,
.cohortsim-alloc-readout span:nth-child(2) {
    color: #1f7a6b;
    font-weight: 800;
}

.cohortsim-hint {
    font-size: 0.8rem;
    color: #7d7699;
    margin-top: 4px;
    line-height: 1.4;
}

.cohortsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.cohortsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f6f3fc;
    border: 1px solid #e4ddf2;
    border-radius: 9px;
    padding: 8px 12px;
}

.cohortsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #2c2552;
}

.cohortsim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.cohortsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.cohortsim-container .btn-primary {
    background: linear-gradient(135deg, #34276e 0%, #4a3a8c 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #fbf8ff;
    box-shadow: 0 6px 16px rgba(52, 39, 110, 0.30);
}

.cohortsim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.cohortsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cdc3e6;
    color: #6a6388;
}

.cohortsim-coach {
    background: #221a4d;
    color: #efeaff;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(34, 26, 77, 0.24);
}

.cohortsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #b8acdf;
    margin-bottom: 8px;
}

.cohortsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.cohortsim-coach-body strong { color: #f0cd7e; }
.cohortsim-coach-body em { color: #ffc1ad; font-style: italic; }

.cohortsim-history,
.cohortsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e1dbee;
    box-shadow: 0 4px 14px rgba(34, 26, 77, 0.06);
}

.cohortsim-history h3,
.cohortsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #221a4d;
}

.cohortsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2c2552;
}

.cohortsim-container table#usfHistoryTable th {
    background: #efe9f8;
    color: #34276e;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #ddd2f0;
}

.cohortsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0ebf8;
}

.cohortsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf8fd;
}

.cohortsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .cohortsim-container {
        padding: 14px;
    }
    .cohortsim-header h1 {
        font-size: 1.7rem;
    }
    .cohortsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .cohortsim-value {
        font-size: 2rem;
    }
    .cohortsim-constraint-bar {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .cohortsim-clock {
        margin-left: 0;
    }
    .cohortsim-period-counter {
        font-size: 0.88rem;
    }
    .cohortsim-alloc-row {
        flex-wrap: wrap;
    }
    .cohortsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .cohortsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

