(function() {
    'use strict';

    class CohortAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Designing the Cohort`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // ---- Numbers reference card (Pohjola contract) ----
            this.CONTRACT = 880;             // EUR 880K fee, in thousands
            this.MARGIN_FLOOR = 24;          // 24% contribution margin floor
            this.DELIVER_BUDGET = 669;       // EUR 669K deliverable cost budget, in thousands
            this.COHORT = 60;                // 60 senior managers
            this.CPL_TARGET = 11.15;         // ~EUR 11,150 cost-per-learner target, in thousands
            this.DAYS_CAP = 12;              // 12 contact days per participant
            this.COMPLETION_FLOOR = 90;      // 90% completion (54 of 60)

            // Element costs, in EUR thousands.
            this.FACULTY_PER_DAY = 35;       // faculty/design cost per contact day
            this.SIM_COST = 70;              // custom simulation
            this.SIM_GOLD_COST = 130;        // two custom simulations
            this.SIM_SKIP_COST = 8;          // cheap case study instead of the sim
            this.COACH_ALL = 108;            // 60 x EUR 1,800
            this.COACH_TARGETED = 36;        // ~20 x EUR 1,800
            this.THREESIXTY_COST = 14.4;     // 60 x EUR 240

            // Concept-correct plays.
            this.WIN_FIT = 70;               // target composite gate
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    objfit: 12,
                    transfer: 8,
                    sponsor: 15,
                    daysUsed: 0,
                    budgetUsed: 0,
                    completion: 78,
                    margin: this.MARGIN_FLOOR,
                    cpl: 0,
                    overScoped: false,
                    marginBroken: false,
                    objfitHistory: [12],
                    transferHistory: [8],
                    sponsorHistory: [15],
                    lastCoach: ``
                };
            }
            // Seed defaults to a MIDDLING / neutral mix (must NOT be the textbook-correct play).
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    approach: `topics`,
                    reconcile: `both`,
                    scope: 45,
                    leadership: 3,
                    commercial: 3,
                    simdays: 2,
                    capstone: 2,
                    peer: 2,
                    coaching: `all`,
                    buildbuy: `buy`,
                    assess: `portfolio`,
                    threesixty: `no`,
                    engage: 50,
                    coord: 20,
                    coo: `cave`,
                    pitch: `richness`,
                    kpi: `completion`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const ap = document.getElementById(`approachInput`);
                const re = document.getElementById(`reconcileInput`);
                const sc = document.getElementById(`scopeInput`);
                if (ap) decisions.approach = ap.value;
                if (re) decisions.reconcile = re.value;
                if (sc) decisions.scope = parseInt(sc.value, 10);
                if (!Number.isFinite(decisions.scope) || decisions.scope < 0 || decisions.scope > 100) {
                    warn(`warn_scope_range`); return false;
                }
            } else if (round === 2) {
                const lead = document.getElementById(`leadershipInput`);
                const comm = document.getElementById(`commercialInput`);
                const sim = document.getElementById(`simdaysInput`);
                const cap = document.getElementById(`capstoneInput`);
                const peer = document.getElementById(`peerInput`);
                const co = document.getElementById(`coachingInput`);
                const bb = document.getElementById(`buildbuyInput`);
                if (lead) decisions.leadership = parseFloat(lead.value);
                if (comm) decisions.commercial = parseFloat(comm.value);
                if (sim) decisions.simdays = parseFloat(sim.value);
                if (cap) decisions.capstone = parseFloat(cap.value);
                if (peer) decisions.peer = parseFloat(peer.value);
                if (co) decisions.coaching = co.value;
                if (bb) decisions.buildbuy = bb.value;
                const parts = [decisions.leadership, decisions.commercial, decisions.simdays, decisions.capstone, decisions.peer];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_days_negative`); return false;
                }
                const total = Math.round((decisions.leadership + decisions.commercial + decisions.simdays + decisions.capstone + decisions.peer) * 10) / 10;
                if (Math.abs(total - this.DAYS_CAP) > 0.001) {
                    warn(`warn_days_total`); return false;
                }
                // If the simulation is bought/built, the sim-days must reflect it (it costs 2 days).
                if ((decisions.buildbuy === `buy` || decisions.buildbuy === `gold`) && decisions.simdays < 2) {
                    warn(`warn_sim_days`); return false;
                }
            } else if (round === 3) {
                const as = document.getElementById(`assessInput`);
                const ts = document.getElementById(`threesixtyInput`);
                const en = document.getElementById(`engageInput`);
                const cd = document.getElementById(`coordInput`);
                if (as) decisions.assess = as.value;
                if (ts) decisions.threesixty = ts.value;
                if (en) decisions.engage = parseInt(en.value, 10);
                if (cd) decisions.coord = parseFloat(cd.value);
                if (!Number.isFinite(decisions.engage) || decisions.engage < 0 || decisions.engage > 100) {
                    warn(`warn_engage_range`); return false;
                }
                if (!Number.isFinite(decisions.coord) || decisions.coord < 0) {
                    warn(`warn_coord_negative`); return false;
                }
            } else if (round === 4) {
                const co = document.getElementById(`cooInput`);
                const pi = document.getElementById(`pitchInput`);
                const kp = document.getElementById(`kpiInput`);
                const cv = document.getElementById(`convictionInput`);
                if (co) decisions.coo = co.value;
                if (pi) decisions.pitch = pi.value;
                if (kp) decisions.kpi = kp.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let objfitDelta = 0, transferDelta = 0, sponsorDelta = 0;
            let completionDelta = 0;
            let spend = 0, days = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Translate the vague brief into prioritized objectives (Common Error 1).
                switch (d.approach) {
                    case `contract`: objfitDelta += 17; sponsorDelta += 8; transferDelta += 2; coachKey = `coach_r1_contract`; break;
                    case `everything`: objfitDelta -= 10; sponsorDelta -= 8; coachKey = `coach_r1_everything`; break;
                    case `topics`: objfitDelta -= 6; sponsorDelta -= 2; coachKey = `coach_r1_topics`; break;
                    case `sponsor`: objfitDelta -= 4; sponsorDelta -= 10; coachKey = `coach_r1_sponsor`; break;
                }

                // Reconcile the CHRO and the COO into ONE ranked objective set.
                switch (d.reconcile) {
                    case `ranked`: objfitDelta += 9; sponsorDelta += 12; transferDelta += 4; if (d.approach === `contract`) coachKey = `coach_r1_sharp`; break;
                    case `chro`: sponsorDelta -= 6; coachKey = `coach_r1_tilt`; break;
                    case `coo`: sponsorDelta -= 6; coachKey = `coach_r1_tilt`; break;
                    case `both`: objfitDelta -= 8; sponsorDelta += 2; coachKey = `coach_r1_both`; break;
                }

                // Out-of-scope discipline — the willingness to say no.
                if (d.scope >= 60) { objfitDelta += 7; sponsorDelta += 4; }
                else if (d.scope <= 25) { objfitDelta -= 8; if (coachKey === `coach_default`) coachKey = `coach_r1_noscope`; }

                summaryKey = (d.approach === `contract` && d.reconcile === `ranked`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Backward design: allocate the scarce 12 days + budget without over-scoping (Errors 2 & 3).
                days = d.leadership + d.commercial + d.simdays + d.capstone + d.peer;

                // Faculty/design cost scales with contact days.
                spend += days * this.FACULTY_PER_DAY;

                // A balanced mix that funds a capstone AND peer learning anchors transfer; a
                // lecture-only split (no capstone, no peer) starves transfer.
                const hasCapstone = d.capstone >= 1.5;
                const hasPeer = d.peer >= 1;
                const hasCommercial = d.commercial >= 2;
                const hasLeadership = d.leadership >= 2;
                if (hasCapstone && hasPeer && hasCommercial && hasLeadership) {
                    objfitDelta += 10; transferDelta += 12; coachKey = `coach_r2_balanced`;
                } else if (hasCapstone && hasPeer) {
                    objfitDelta += 5; transferDelta += 7;
                } else {
                    objfitDelta += 2; transferDelta -= 6; coachKey = `coach_r2_lecture`;
                }

                // Build-vs-buy the simulation.
                switch (d.buildbuy) {
                    case `buy`: spend += this.SIM_COST; objfitDelta += 8; transferDelta += 6; break;
                    case `skip`: spend += this.SIM_SKIP_COST; objfitDelta -= 2; transferDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r2_skip` : coachKey; break;
                    case `gold`: spend += this.SIM_GOLD_COST; objfitDelta += 4; transferDelta += 4; coachKey = `coach_r2_gold`; break;
                }

                // 1:1 coaching scale — stacking it on all 60 blows the per-learner economics (Error 3).
                // Concentrating coaching on the ~20 with the biggest transition role is the disciplined
                // play: it drives MORE transfer per euro, while spreading 1:1 coaching thin across all 60
                // dilutes the attention (diminishing returns) AND costs 3x. The disciplined 'targeted'
                // choice must therefore out-score 'all' on the KPIs as well as on margin/cost-per-learner —
                // never let the wasteful stacking play KPI-dominate the correct one.
                switch (d.coaching) {
                    case `targeted`: spend += this.COACH_TARGETED; transferDelta += 8; sponsorDelta += 3; coachKey = (coachKey === `coach_r2_balanced`) ? `coach_r2_disciplined` : coachKey; break;
                    case `all`: spend += this.COACH_ALL; transferDelta += 6; sponsorDelta += 3; coachKey = `coach_r2_coachall`; break;
                    case `none`: transferDelta += 1; coachKey = (coachKey === `coach_default`) ? `coach_r2_nocoach` : coachKey; break;
                }

                summaryKey = (hasCapstone && hasPeer && d.coaching !== `all` && d.buildbuy !== `gold`) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Assessment & transfer (Common Error 4).
                switch (d.assess) {
                    case `blend`: transferDelta += 15; sponsorDelta += 11; objfitDelta += 3; coachKey = `coach_r3_blend`; break;
                    case `portfolio`: transferDelta += 2; sponsorDelta -= 8; coachKey = `coach_r3_portfolio`; break;
                    case `simscore`: transferDelta += 4; sponsorDelta -= 4; coachKey = `coach_r3_simscore`; break;
                    case `exam`: transferDelta -= 8; sponsorDelta -= 6; completionDelta -= 6; coachKey = `coach_r3_exam`; break;
                }

                // 360 behavioural evidence — the CHRO's proof.
                if (d.threesixty === `yes`) { spend += this.THREESIXTY_COST; sponsorDelta += 7; transferDelta += 2; }
                else { sponsorDelta -= 4; if (coachKey === `coach_default`) coachKey = `coach_r3_no360`; }

                // Engagement design vs pure rigour — protects the 90% completion floor.
                if (d.engage >= 60) { transferDelta += 6; completionDelta += 12; }
                else if (d.engage <= 25) { transferDelta -= 6; completionDelta -= 12; coachKey = `coach_r3_lowengage`; }
                else { completionDelta += 3; }

                // Capstone coordination — credible transfer is coordination-heavy.
                spend += d.coord;
                if (d.coord >= 25) { transferDelta += 6; sponsorDelta += 2; }
                else if (d.coord >= 10) { transferDelta += 3; }
                else { transferDelta -= 6; coachKey = `coach_r3_nocoord`; }

                summaryKey = (d.assess === `blend` && d.threesixty === `yes`) ? `sum_r3_good` : (d.assess === `exam` ? `sum_r3_lecture` : `sum_r3_weak`);
            } else if (round === 4) {
                // Pitch & defend the cuts (Common Error 5).
                switch (d.coo) {
                    case `tradeoff`: objfitDelta += 5; sponsorDelta += 13; transferDelta += 2; coachKey = `coach_r4_tradeoff`; break;
                    case `cave`: objfitDelta -= 10; sponsorDelta -= 6; completionDelta -= 6; days += 2; coachKey = `coach_r4_cave`; break;
                    case `refuse`: sponsorDelta -= 8; coachKey = `coach_r4_refuse`; break;
                }

                // The pitch framing.
                switch (d.pitch) {
                    case `design`: sponsorDelta += 6; objfitDelta += 3; if (d.coo === `tradeoff`) coachKey = `coach_r4_strong`; break;
                    case `richness`: sponsorDelta -= 4; objfitDelta -= 2; coachKey = `coach_r4_richness`; break;
                    case `price`: sponsorDelta -= 2; coachKey = `coach_r4_price`; break;
                }

                // KPI commitment.
                switch (d.kpi) {
                    case `full`: sponsorDelta += 5; transferDelta += 3; break;
                    case `completion`: sponsorDelta += 1; break;
                    case `none`: sponsorDelta -= 6; transferDelta -= 4; coachKey = `coach_r4_nokpi`; break;
                }

                // Conviction nudges sponsor satisfaction around a neutral 60.
                sponsorDelta += Math.round((d.conviction - 60) / 8);

                summaryKey = (d.coo === `tradeoff` && d.pitch === `design`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Resource accounting ----
            ds.daysUsed = Math.round((ds.daysUsed + days) * 10) / 10;
            ds.budgetUsed = Math.round((ds.budgetUsed + spend) * 10) / 10;

            // Over-scoping the 12 contact days erodes every KPI (the design cannot be delivered).
            if (ds.daysUsed > this.DAYS_CAP + 0.001) {
                const over = ds.daysUsed - this.DAYS_CAP;
                ds.overScoped = true;
                objfitDelta -= over * 6;
                transferDelta -= over * 5;
                sponsorDelta -= over * 4;
                completionDelta -= over * 4;
                if (round === this.ROUNDS.length || d.coo === `cave`) coachKey = `coach_overscoped`;
            }

            // Margin and cost-per-learner from cumulative deliverable spend.
            const spendForMargin = Math.min(ds.budgetUsed, this.CONTRACT);
            ds.margin = Math.round(((this.CONTRACT - spendForMargin) / this.CONTRACT) * 1000) / 10;
            ds.cpl = Math.round((ds.budgetUsed / this.COHORT) * 1000) / 1000; // EUR thousands per learner

            // Breaching the deliverable budget / margin floor punishes sponsor + objective fit.
            if (ds.budgetUsed > this.DELIVER_BUDGET + 0.001) {
                ds.marginBroken = true;
                const overK = ds.budgetUsed - this.DELIVER_BUDGET;
                sponsorDelta -= Math.min(20, overK / 6);
                objfitDelta -= Math.min(12, overK / 10);
                if (coachKey === `coach_default` || coachKey === `coach_r2_coachall`) coachKey = `coach_marginbroken`;
            }

            // ---- Apply deltas with headroom (clamped 0–100) ----
            ds.objfit = Math.max(0, Math.min(100, ds.objfit + objfitDelta));
            ds.transfer = Math.max(0, Math.min(100, ds.transfer + transferDelta));
            ds.sponsor = Math.max(0, Math.min(100, ds.sponsor + sponsorDelta));
            ds.completion = Math.max(0, Math.min(100, ds.completion + completionDelta));

            ds.objfitHistory.push(Math.round(ds.objfit));
            ds.transferHistory.push(Math.round(ds.transfer));
            ds.sponsorHistory.push(Math.round(ds.sponsor));

            // v1.1.0 fix: persist instructor-card composite every period.
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                objfit: Math.round(ds.objfit),
                objfitDelta: Math.round(objfitDelta),
                transfer: Math.round(ds.transfer),
                transferDelta: Math.round(transferDelta),
                sponsor: Math.round(ds.sponsor),
                sponsorDelta: Math.round(sponsorDelta),
                daysUsed: ds.daysUsed,
                budgetUsed: ds.budgetUsed,
                margin: ds.margin,
                completion: Math.round(ds.completion),
                cpl: ds.cpl,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoneyK(valueK) {
            // valueK is in EUR thousands; render locale-aware with the € symbol.
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const n = Math.round(Number(valueK) || 0);
            if (lang === `es`) return n + `k €`;
            return `€` + n + `k`;
        }

        _fmtMoneyPerLearner(valueK) {
            // cost-per-learner stored in EUR thousands; show as full euros, locale-aware.
            // Group thousands manually so the output is deterministic regardless of the
            // runtime's Intl/ICU data: Spanish uses "." (symbol after), English "," (symbol before).
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const euros = Math.round((Number(valueK) || 0) * 1000);
            const sep = (lang === `es`) ? `.` : `,`;
            const grouped = String(euros).replace(/\B(?=(\d{3})+(?!\d))/g, sep);
            return (lang === `es`) ? (grouped + ` €`) : (`€` + grouped);
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);
            uiManager.bind(`objfitDisplay`, `domainState.objfit`, (v) => Math.round(v));
            uiManager.bind(`transferDisplay`, `domainState.transfer`, (v) => Math.round(v));
            uiManager.bind(`sponsorDisplay`, `domainState.sponsor`, (v) => Math.round(v));
            uiManager.bind(`marginDisplay`, `domainState.margin`, (v) => {
                const card = document.querySelector(`.cohortsim-card-margin`);
                if (card) {
                    card.classList.toggle(`cohortsim-margin-ok`, Number(v) >= this.MARGIN_FLOOR);
                    card.classList.toggle(`cohortsim-margin-fail`, Number(v) < this.MARGIN_FLOOR);
                }
                return Math.round(Number(v)) + `%`;
            });
            const self = this;
            uiManager.bind(`daysDisplay`, `domainState.daysUsed`, (v) => {
                const wrap = document.querySelectorAll(`.cohortsim-constraint`)[0];
                if (wrap) wrap.classList.toggle(`cohortsim-over`, Number(v) > self.DAYS_CAP + 0.001);
                return Number(v).toFixed(1) + ` / 12`;
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const wrap = document.querySelectorAll(`.cohortsim-constraint`)[1];
                if (wrap) wrap.classList.toggle(`cohortsim-over`, Number(v) > self.DELIVER_BUDGET + 0.001);
                return self._fmtMoneyK(v) + ` / ` + self._fmtMoneyK(self.DELIVER_BUDGET);
            });
            uiManager.bind(`completionDisplay`, `domainState.completion`, (v) => {
                const wrap = document.querySelectorAll(`.cohortsim-constraint`)[2];
                if (wrap) wrap.classList.toggle(`cohortsim-under`, Number(v) < self.COMPLETION_FLOOR);
                return Math.round(Number(v)) + `%`;
            });
            uiManager.bind(`cplDisplay`, `domainState.cpl`, (v) => {
                const wrap = document.querySelectorAll(`.cohortsim-constraint`)[3];
                if (wrap) wrap.classList.toggle(`cohortsim-over`, Number(v) > self.CPL_TARGET + 0.001);
                return self._fmtMoneyPerLearner(v);
            });

            // Scope slider readout.
            const sc = document.getElementById(`scopeInput`);
            const scReadout = document.getElementById(`scopeReadout`);
            if (sc && scReadout) {
                scReadout.textContent = sc.value;
                sc.addEventListener(`input`, function() { scReadout.textContent = sc.value; });
            }

            // Engagement slider readout.
            const en = document.getElementById(`engageInput`);
            const enReadout = document.getElementById(`engageReadout`);
            if (en && enReadout) {
                enReadout.textContent = en.value;
                en.addEventListener(`input`, function() { enReadout.textContent = en.value; });
            }

            // Contact-day live total.
            const dayIds = [`leadershipInput`, `commercialInput`, `simdaysInput`, `capstoneInput`, `peerInput`];
            const daysReadout = document.getElementById(`daysReadout`);
            const recompute = function() {
                let total = 0;
                dayIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 10) / 10;
                if (daysReadout) daysReadout.textContent = total.toFixed(1);
                const bar = document.querySelector(`.cohortsim-alloc-readout`);
                if (bar) bar.style.color = (Math.abs(total - self.DAYS_CAP) > 0.001) ? `#c0392b` : ``;
            };
            dayIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

