        _composite(ds) {
            const objfit = Math.round(ds.objfit);
            const transfer = Math.round(ds.transfer);
            const sponsor = Math.round(ds.sponsor);
            return Math.round(objfit * 0.30 + transfer * 0.35 + sponsor * 0.35);
        }

        _cl(key) {
            return (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(key) : key;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const objfit = Math.round(ds.objfit);
            const transfer = Math.round(ds.transfer);
            const sponsor = Math.round(ds.sponsor);
            const completion = Math.round(ds.completion);
            const margin = ds.margin;
            const cpl = ds.cpl;

            const composite = this._composite(ds);
            const marginOk = margin >= this.MARGIN_FLOOR && !ds.marginBroken;
            const completionOk = completion >= this.COMPLETION_FLOOR;
            const deliverable = !ds.overScoped;
            const constraintsHeld = marginOk && completionOk && deliverable;

            let performanceKey = `grade_incoherent`;
            if (composite >= 78 && constraintsHeld) performanceKey = `grade_signed`;
            else if (composite >= this.WIN_FIT && constraintsHeld) performanceKey = `grade_coherent`;
            else if (composite >= this.WIN_FIT && !constraintsHeld) performanceKey = `grade_undeliverable`;
            else if (composite >= 50) performanceKey = `grade_workable`;
            const performance = window.mySimulation.t(performanceKey);
            const met = (composite >= this.WIN_FIT) && constraintsHeld;

            const insights = [];
            if (composite >= this.WIN_FIT && constraintsHeld) insights.push(window.mySimulation.t(`insight_coherent`));
            else if (composite >= this.WIN_FIT && !constraintsHeld) insights.push(window.mySimulation.t(`insight_undeliverable`));
            else insights.push(window.mySimulation.t(`insight_incoherent`));

            if (ds.overScoped) insights.push(window.mySimulation.t(`insight_overscoped`));
            if (ds.marginBroken || margin < this.MARGIN_FLOOR) insights.push(window.mySimulation.t(`insight_margin`));
            if (completion < this.COMPLETION_FLOOR) insights.push(window.mySimulation.t(`insight_completion`));
            if (transfer < 45) insights.push(window.mySimulation.t(`insight_transfer`));
            if (cpl > this.CPL_TARGET) insights.push(window.mySimulation.t(`insight_cpl`));
            if (composite >= 78 && constraintsHeld) insights.push(window.mySimulation.t(`insight_renewal`));

            return {
                objfit: objfit,
                transfer: transfer,
                sponsor: sponsor,
                completion: completion,
                margin: margin,
                composite: composite,
                constraintsHeld: constraintsHeld,
                overScoped: !!ds.overScoped,
                marginBroken: !!ds.marginBroken,
                completionOk: completionOk,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k, v) => window.mySimulation.t(k, v);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="aurora-cm-badge ` + (s.met ? `aurora-cm-met` : `aurora-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (s.overScoped) badges.push(`<span class="aurora-cm-badge aurora-cm-fail">` + t(`cm_fail_scope`) + `</span>`);
            if (s.marginBroken) badges.push(`<span class="aurora-cm-badge aurora-cm-fail">` + t(`cm_fail_margin`) + `</span>`);
            if (s.completionOk === false) badges.push(`<span class="aurora-cm-badge aurora-cm-fail">` + t(`cm_fail_completion`) + `</span>`);
            const kpi = (label, val) => `<div class="aurora-cm-metric"><div class="aurora-cm-metric-val">` + val + `</div><div class="aurora-cm-metric-lbl">` + label + `</div></div>`;
            const kpis = kpi(t(`cm_fit`), (s.objfit != null ? s.objfit : 0)) + kpi(t(`cm_transfer`), (s.transfer != null ? s.transfer : 0)) + kpi(t(`cm_sponsor`), (s.sponsor != null ? s.sponsor : 0)) + kpi(t(`cm_margin`), (s.margin != null ? s.margin : 0) + `%`);
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="aurora-cm">`
                + `<div class="aurora-cm-head"><div class="aurora-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="aurora-cm-scorewrap"><span class="aurora-cm-score">` + score + `</span><span class="aurora-cm-score-max">/100</span></div>`
                + `<div class="aurora-cm-grade">` + grade + `</div>`
                + `<div class="aurora-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="aurora-cm-metrics">` + kpis + `</div>`
                + `<div class="aurora-cm-insights"><div class="aurora-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.overScoped) return window.mySimulation.t(`hint_overscoped`);
            if (ds.marginBroken || ds.margin < this.MARGIN_FLOOR) return window.mySimulation.t(`hint_margin`);
            if (ds.completion < this.COMPLETION_FLOOR && state.currentPeriod >= 3) return window.mySimulation.t(`hint_completion`);
            if (ds.transfer < 35) return window.mySimulation.t(`hint_transfer`);
            if (ds.objfit < 35) return window.mySimulation.t(`hint_objfit`);
            if (ds.objfit >= 70 && ds.transfer >= 60 && ds.sponsor >= 65) return window.mySimulation.t(`hint_strong`);
            return null;
        }

